import { accountApi, businessRequest, initializeBusinessPage } from './account.js';
import { quizLevels, quizQuestions } from './data/quiz-questions.js';
import { createQuizGame, currentQuizQuestion, quizAction } from './quiz-state.js';

const root = document.querySelector('#business-activities-app');
const state = { user: null, orgId: '', workspace: null, activities: [], quizzes: [], screen: 'list', activity: null, quizGame: null, quizPool: [], quizUsed: [], quizTitle: 'クイズ', index: 0, phase: 'question', names: [], error: '', busy: false, requestId: 0, editing: null };
let authSubscribed = false;
let activityDeepLinkConsumed = false;
const esc = (value = '') => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const orgIdOf = (org) => org.organizationId || org.organization_id || org.id || '';
const roleCanEdit = () => ['owner', 'admin'].includes(state.workspace?.role);
const contentAllowed = (key) => state.workspace?.contentFlags?.[key] !== false;
const currentCard = () => state.activity?.cards?.[state.index] || null;

function shell(body) { root.setAttribute('aria-busy', state.busy ? 'true' : 'false'); root.innerHTML = `<div class="shell"><header class="topbar"><a class="brand" href="/business.html?orgId=${encodeURIComponent(state.orgId)}">Mingle.Cards</a><span>法人アクティビティ</span><span class="spacer"></span><a href="/business.html?orgId=${encodeURIComponent(state.orgId)}">企業スペースへ戻る</a></header>${state.error ? `<div class="notice error activity-error" role="alert">${esc(state.error)}</div>` : ''}${body}</div>`; }
function focusHeading() { requestAnimationFrame(() => root.querySelector('[data-focus]')?.focus()); }
function activityLabel(activity) { return activity.kind === 'prediction' ? '同僚予想' : '会話'; }
function activityList() {
  state.screen = 'list';
  const cards = contentAllowed('businessActivities') ? state.activities.map((activity) => `<article class="activity-card"><h2>${esc(activity.title)}</h2><p>${esc(activity.description)}</p><small>${activity.minParticipants}〜${activity.maxParticipants}人 · ${activityLabel(activity)} · ${activity.cardCount ?? activity.cards?.length ?? 0}枚</small><br><button class="primary" data-start-activity="${esc(activity.id)}" type="button">はじめる</button></article>`).join('') : '<p class="activity-muted">法人アクティビティは組織で無効です。</p>';
  const quizzes = contentAllowed('customQuiz') ? state.quizzes.map((quiz) => `<article class="activity-card"><h2>${esc(quiz.title)}</h2><p>${esc(quiz.description)}</p><small>${quiz.status === 'published' ? '公開中' : '下書き'} · ${(quiz.questions || []).length}問</small><br>${quiz.status === 'published' ? `<button class="primary" data-start-quiz="${esc(quiz.id)}" type="button">クイズを開始</button>` : ''}${roleCanEdit() ? ` <button type="button" data-edit-quiz="${esc(quiz.id)}">編集</button>` : ''}</article>`).join('') : '<p class="activity-muted">会社を知るクイズは組織で無効です。</p>';
  const levels = quizLevels.map((level) => `<button type="button" data-start-general="${esc(level.id)}">${esc(level.label)}</button>`).join('');
  shell(`<section class="panel"><h1 tabindex="-1" data-focus>法人アクティビティ</h1><p class="muted">会話の回答や録音、個人の履歴は保存しません。口頭で答えたくないカードはパスできます。</p><h2>オンボーディング・会話</h2><div class="activity-grid">${cards || '<p class="activity-muted">利用できる活動がありません。</p>'}</div><h2>会社を知るクイズ</h2>${roleCanEdit() && contentAllowed('customQuiz') ? '<p><button class="primary" data-new-quiz type="button">＋クイズを作成</button></p>' : ''}<div class="activity-grid">${quizzes || '<p class="activity-muted">公開されたクイズはありません。</p>'}</div>${contentAllowed('generalQuiz') ? `<h2>一般クイズ</h2><p class="muted">難易度を選んで、問題と解説を順に見ます。</p><div class="activity-options">${levels}</div>` : ''}</section>`);
  bindList(); focusHeading();
}
function setupActivity(activity) {
  if (!activity) return activityList();
  state.screen = 'setup'; state.activity = activity; state.quizGame = null;
  const count = state.names.length >= activity.minParticipants && state.names.length <= activity.maxParticipants ? state.names.length : activity.minParticipants;
  state.names = Array.from({ length: count }, (_, index) => state.names[index] || '');
  const countOptions = activity.minParticipants === activity.maxParticipants ? `<span class="participant-fixed">参加人数：${count}人</span>` : `<label>参加人数<select data-participant-count>${Array.from({ length: activity.maxParticipants - activity.minParticipants + 1 }, (_, index) => activity.minParticipants + index).map((value) => `<option value="${value}" ${value === count ? 'selected' : ''}>${value}人</option>`).join('')}</select></label>`;
  const needsNames = activity.kind === 'prediction';
  const nameFields = needsNames ? `<div class="participant-fields">${state.names.map((name, index) => `<label>${index + 1}人目の呼び名<input data-participant-name="${index}" maxlength="40" value="${esc(name)}" placeholder="呼び名" required></label>`).join('')}</div>` : '<p class="muted">参加人数だけ選んで、その場で声に出して答えます。</p>';
  shell(`<section class="panel activity-setup"><h1 tabindex="-1" data-focus>${esc(activity.title)}</h1><p class="muted">${esc(activity.description)}</p><p class="setup-rule">${activity.kind === 'prediction' ? '予想する人と答える人を交代します。予想内容は本人に見えません。' : '答えや録音、個人の履歴は保存しません。'}</p>${countOptions}${nameFields}<p class="form-error" role="alert">${esc(state.error)}</p><div class="actions"><button class="primary" data-start-confirm type="button">準備してはじめる</button><button data-back type="button">戻る</button></div></section>`);
  bindSetup(); focusHeading();
}
function syncSetupNames() { root.querySelectorAll('[data-participant-name]').forEach((input) => { state.names[Number(input.dataset.participantName)] = input.value; }); }
function bindSetup() { root.querySelector('[data-participant-count]')?.addEventListener('change', (event) => { syncSetupNames(); const count = Number(event.currentTarget.value); state.names = Array.from({ length: count }, (_, index) => state.names[index] || ''); setupActivity(state.activity); }); root.querySelector('[data-start-confirm]')?.addEventListener('click', startActivity); root.querySelector('[data-back]')?.addEventListener('click', activityList); }
async function startActivity() {
  if (state.busy) return; syncSetupNames();
  if (state.activity.kind === 'prediction' && state.names.some((name) => !String(name).trim())) { state.error = '参加者の呼び名を入力してください。'; setupActivity(state.activity); return; }
  state.busy = true; state.error = ''; state.quizGame = null; renderBusy(); const request = ++state.requestId;
  try { const response = await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/activities/${encodeURIComponent(state.activity.id)}/sessions`, { method: 'POST', body: { participantCount: state.names.length } }); if (request !== state.requestId) return; state.activity = response.activity || state.activity; state.index = 0; state.phase = 'question'; state.screen = 'activity'; }
  catch (error) { if (request === state.requestId) state.error = error?.message || '活動を開始できませんでした。'; }
  finally { if (request === state.requestId) { state.busy = false; render(); } }
}
function renderBusy() { root.querySelectorAll('button, input, select').forEach((element) => { element.disabled = true; }); root.setAttribute('aria-busy', 'true'); }
function activityComplete() { const repeatable = state.activity.id === 'meeting-checkin'; shell(`<section class="panel activity-game"><h1 tabindex="-1" data-focus>おつかれさまでした</h1><p class="muted">会話の回答や録音、個人の履歴は保存していません。</p><div class="actions">${repeatable ? '<button class="primary" data-continue-activity type="button">別の問い</button>' : ''}<button data-back type="button">一覧へ戻る</button></div></section>`); bindCommon(); root.querySelector('[data-continue-activity]')?.addEventListener('click', () => { if (state.activity.cards.length > 1) state.activity.cards.push(state.activity.cards.shift()); state.index = 0; state.phase = 'question'; activityGame(); }); focusHeading(); }
function activityGame() {
  const cardLimit = state.activity?.id === 'meeting-checkin' ? 1 : state.activity?.cards?.length;
  if (!state.activity?.cards?.length || state.index >= cardLimit) return activityComplete();
  const card = currentCard();
  if (state.activity.kind === 'prediction') { const predictor = state.index % 2; const answerer = 1 - predictor; if (state.phase === 'question') shell(`<section class="panel activity-game"><p class="muted">${state.index + 1} / ${state.activity.cards.length}</p><h1 tabindex="-1" data-focus>${esc(state.names[predictor])}の予想</h1><p class="muted">${esc(state.names[answerer])}ならどちらを選ぶ？</p><p class="activity-question">${esc(card.question)}</p><div class="activity-options">${card.options.map((option, index) => `<button type="button" data-predict="${index}">${esc(option)}</button>`).join('')}</div><div class="actions"><button data-pass type="button">パス</button><button data-back type="button">退出</button></div></section>`); else if (state.phase === 'answer') shell(`<section class="panel activity-game"><p class="muted">${state.index + 1} / ${state.activity.cards.length}</p><h1 tabindex="-1" data-focus>${esc(state.names[answerer])}の番</h1><p class="muted">予想内容は見えません。本人の答えを選んでください。</p><p class="activity-question">${esc(card.question)}</p><div class="activity-options">${card.options.map((option, index) => `<button type="button" data-answer="${index}">${esc(option)}</button>`).join('')}</div><div class="actions"><button data-pass type="button">パス</button><button data-back type="button">退出</button></div></section>`); else shell(`<section class="panel activity-game"><h1 tabindex="-1" data-focus>答え合わせ</h1><p class="activity-question">${esc(card.options[state.answer])}</p><p class="muted">${esc(state.names[predictor])}の予想：${esc(card.options[state.prediction])}</p><p class="muted">${state.answer === state.prediction ? '予想が当たりました。' : '今回は予想と違いました。'}</p><div class="actions"><button class="primary" data-next type="button">${state.index + 1 === state.activity.cards.length ? '完了' : '次の問題'}</button><button data-back type="button">退出</button></div></section>`); }
  else shell(`<section class="panel activity-game"><p class="muted">${state.index + 1} / ${state.activity.id === 'meeting-checkin' ? 1 : state.activity.cards.length}</p><h1 tabindex="-1" data-focus>会話カード</h1><p class="activity-question">${esc(card.question)}</p><div class="actions"><button class="primary" data-next type="button">${state.activity.id === 'meeting-checkin' ? 'この1枚でおわる' : (state.index + 1 === state.activity.cards.length ? '完了' : '次のカード')}</button><button data-pass type="button">パス</button><button data-back type="button">退出</button></div><p class="muted">答えたくないときはパスできます。</p></section>`);
  bindGame(); focusHeading();
}
function quizGame() { const question = currentQuizQuestion(state.quizGame); if (!question) return quizComplete(); const round = state.quizGame.cursor + 1; shell(`<section class="panel activity-game"><p class="muted">${esc(state.quizTitle)} · ${round} / ${state.quizGame.questions.length}</p><h1 tabindex="-1" data-focus>${state.quizGame.phase === 'question' ? '問題カード' : '正解・解説カード'}</h1><p class="activity-question">${esc(state.quizGame.phase === 'question' ? question.question : question.answer)}</p>${state.quizGame.phase === 'question' ? '<button class="primary" data-reveal type="button">正解を見る</button>' : `<p class="muted">${esc(question.explanation || '')}</p><button class="primary" data-next type="button">${round === state.quizGame.questions.length ? 'おわる' : '次の問題'}</button>`}<div class="actions"><button data-back type="button">退出</button></div></section>`); bindGame(); focusHeading(); }
function quizComplete() { const total = state.quizGame.questions.length; shell(`<section class="panel activity-game"><h1 tabindex="-1" data-focus>${esc(state.quizTitle)}・${total}問完了</h1><p class="muted">このセットの問題を終えました。</p><div class="actions"><button class="primary" data-quiz-continue type="button">つづける</button><button data-back type="button">一覧へ戻る</button></div></section>`); bindCommon(); root.querySelector('[data-quiz-continue]')?.addEventListener('click', () => { state.quizGame = createQuizGame({ questions: state.quizPool, questionCount: 6, levelId: state.quizGame.levelId, usedQuestionIds: state.quizGame.usedQuestionIds }); state.quizUsed = state.quizGame.usedQuestionIds; quizGame(); }); focusHeading(); }
function startQuizGame(questions, title = 'クイズ', levelId = 'all') { state.quizPool = (Array.isArray(questions) ? questions : []).map((question, index) => ({ ...question, id: question.id || `${levelId}-${index + 1}`, explanation: question.explanation || '' })); state.quizTitle = title; state.quizUsed = []; state.quizGame = createQuizGame({ questions: state.quizPool, levelId, questionCount: 6, usedQuestionIds: state.quizUsed }); state.quizUsed = state.quizGame.usedQuestionIds; state.screen = 'quiz'; state.error = ''; quizGame(); }
async function startCompanyQuiz(id) { if (state.busy) return; state.busy = true; state.error = ''; renderBusy(); const request = ++state.requestId; try { const response = await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/quizzes/${encodeURIComponent(id)}`, { method: 'POST' }); if (request !== state.requestId) return; startQuizGame(response.quiz?.questions || [], response.quiz?.title || '会社を知るクイズ'); } catch (error) { if (request === state.requestId) state.error = error?.message || 'クイズを開始できませんでした。'; } finally { if (request === state.requestId) { state.busy = false; render(); } } }
function readEditor() { if (!state.editing) return; const title = root.querySelector('[name="title"]')?.value ?? state.editing.title; const description = root.querySelector('[name="description"]')?.value ?? state.editing.description; const status = root.querySelector('[name="status"]')?.value ?? state.editing.status; const questions = [...root.querySelectorAll('[data-row]')].map((row) => Object.fromEntries([...row.querySelectorAll('[data-q]')].map((input) => [input.dataset.q, input.value]))); state.editing = { ...state.editing, title, description, status, questions }; }
function editor(quiz = { title: '', description: '', status: 'draft', questions: [{ question: '', answer: '', explanation: '' }] }) { state.screen = 'editor'; const sameQuiz = Boolean(quiz.id) && state.editing?.id === quiz.id; state.editing = sameQuiz ? state.editing : JSON.parse(JSON.stringify(quiz)); const current = state.editing; shell(`<section class="panel"><h1 tabindex="-1" data-focus>${current.id ? 'クイズを編集' : '会社を知るクイズを作成'}</h1><form class="activity-editor" data-quiz-form><label>タイトル<input name="title" maxlength="120" required value="${esc(current.title)}"></label><label>説明<textarea name="description" maxlength="500">${esc(current.description)}</textarea></label><label>公開状態<select name="status"><option value="draft" ${current.status === 'draft' ? 'selected' : ''}>非公開（下書き）</option><option value="published" ${current.status === 'published' ? 'selected' : ''}>公開</option></select></label><div data-quiz-rows>${current.questions.map((question, index) => `<div class="quiz-row" data-row="${index}"><label>問題<input data-q="question" required maxlength="1000" value="${esc(question.question)}"></label><label>正解<input data-q="answer" required maxlength="1000" value="${esc(question.answer)}"></label><label>解説<textarea data-q="explanation" maxlength="2000">${esc(question.explanation || '')}</textarea></label>${index ? '<button type="button" data-remove-row>この問題を削除</button>' : ''}</div>`).join('')}</div><div class="actions"><button type="button" data-add-row>問題を追加</button><button class="primary" type="submit">保存</button><button type="button" data-back>戻る</button></div></form></section>`); bindEditor(); focusHeading(); }
function bindCommon() { root.querySelectorAll('[data-back]').forEach((button) => button.addEventListener('click', activityList)); }
function bindList() { root.querySelectorAll('[data-start-activity]').forEach((button) => button.addEventListener('click', () => setupActivity(state.activities.find((activity) => activity.id === button.dataset.startActivity)))); root.querySelectorAll('[data-start-quiz]').forEach((button) => button.addEventListener('click', () => startCompanyQuiz(button.dataset.startQuiz))); root.querySelectorAll('[data-start-general]').forEach((button) => button.addEventListener('click', () => { const level = button.dataset.startGeneral; const label = quizLevels.find((item) => item.id === level)?.label || level; startQuizGame(quizQuestions.filter((question) => question.level === level), `一般クイズ・${label}`, level); })); root.querySelectorAll('[data-edit-quiz]').forEach((button) => button.addEventListener('click', () => editor(state.quizzes.find((quiz) => quiz.id === button.dataset.editQuiz)))); root.querySelector('[data-new-quiz]')?.addEventListener('click', () => editor()); }
function bindGame() { bindCommon(); root.querySelector('[data-reveal]')?.addEventListener('click', () => { state.quizGame = quizAction(state.quizGame, 'reveal'); quizGame(); }); root.querySelectorAll('[data-predict]').forEach((button) => button.addEventListener('click', (event) => { state.prediction = Number(event.currentTarget.dataset.predict); state.phase = 'answer'; activityGame(); })); root.querySelectorAll('[data-answer]').forEach((button) => button.addEventListener('click', (event) => { state.answer = Number(event.currentTarget.dataset.answer); state.phase = 'result'; activityGame(); })); root.querySelector('[data-next]')?.addEventListener('click', () => { if (state.quizGame) { state.quizGame = quizAction(state.quizGame, 'next'); quizGame(); } else { state.index += 1; state.phase = 'question'; activityGame(); } }); root.querySelectorAll('[data-pass]').forEach((button) => button.addEventListener('click', () => { state.index += 1; state.phase = 'question'; activityGame(); })); }
function render() { if (state.screen === 'list') activityList(); else if (state.screen === 'setup') setupActivity(state.activity); else if (state.screen === 'activity') activityGame(); else if (state.screen === 'quiz') quizGame(); else if (state.screen === 'editor') editor(state.editing); }
function bindEditor() { root.querySelector('[data-back]')?.addEventListener('click', activityList); root.querySelector('[data-add-row]')?.addEventListener('click', () => { readEditor(); state.editing.questions.push({ question: '', answer: '', explanation: '' }); editor(state.editing); }); root.querySelectorAll('[data-remove-row]').forEach((button) => button.addEventListener('click', () => { readEditor(); state.editing.questions.splice(Number(button.closest('[data-row]').dataset.row), 1); editor(state.editing); })); root.querySelector('[data-quiz-form]')?.addEventListener('submit', async (event) => { event.preventDefault(); if (state.busy) return; readEditor(); const payload = { title: state.editing.title.trim(), description: state.editing.description.trim(), status: state.editing.status, questions: state.editing.questions }; if (!payload.title || payload.questions.some((question) => !question.question.trim() || !question.answer.trim())) { state.error = 'タイトル、問題、正解を入力してください。'; editor(state.editing); return; } state.busy = true; state.error = ''; renderBusy(); const request = ++state.requestId; try { const path = state.editing.id ? `/organizations/${encodeURIComponent(state.orgId)}/quizzes/${encodeURIComponent(state.editing.id)}` : `/organizations/${encodeURIComponent(state.orgId)}/quizzes`; await businessRequest(path, { method: state.editing.id ? 'PATCH' : 'POST', body: payload }); if (request === state.requestId) { state.busy = false; await load(); } } catch (error) { if (request === state.requestId) { state.busy = false; state.error = error?.message || '保存できませんでした。'; editor(state.editing); } } }); }
async function load() { const request = ++state.requestId; state.error = ''; try { const user = await accountApi.me(); if (request !== state.requestId) return; state.user = user; if (!authSubscribed && typeof accountApi.onAuthStateChange === 'function') { accountApi.onAuthStateChange((event) => { if (event === 'TOKEN_REFRESHED') return; state.requestId += 1; state.busy = false; state.activity = null; state.quizGame = null; state.editing = null; state.screen = 'list'; load(); }); authSubscribed = true; } const orgs = (await businessRequest('/organizations')).organizations || []; const wanted = new URLSearchParams(location.search).get('orgId'); state.orgId = wanted && orgs.some((org) => orgIdOf(org) === wanted) ? wanted : orgIdOf(orgs[0]); if (!state.orgId) throw new Error('組織がありません。'); state.workspace = await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/workspace`); const [activityResult, quizResult] = await Promise.allSettled([businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/activities`), businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/quizzes`)]); if (request !== state.requestId) return; if (activityResult.status === 'rejected' && contentAllowed('businessActivities')) throw activityResult.reason; if (quizResult.status === 'rejected' && contentAllowed('customQuiz')) throw quizResult.reason; state.activities = activityResult.status === 'fulfilled' ? (activityResult.value.activities || []) : []; state.quizzes = quizResult.status === 'fulfilled' ? (quizResult.value.quizzes || []) : []; const requested = activityDeepLinkConsumed ? '' : new URLSearchParams(location.search).get('activity'); activityDeepLinkConsumed = true; const activity = requested && state.activities.find((item) => item.id === requested); if (activity) { setupActivity(activity); } else { activityList(); } } catch (error) { if (request !== state.requestId) return; state.error = error?.message || '読み込みに失敗しました。'; shell(`<section class="panel"><h1 tabindex="-1" data-focus>法人アクティビティ</h1><p>${esc(state.error)}</p><a href="/business.html">企業スペースへ戻る</a></section>`); focusHeading(); } }
initializeBusinessPage(load);
